def render_two_col_table(pairs, key_width):
    lines = []
    idx = 0
    while idx < len(pairs):
        key, value = pairs[idx]
        lines.append(f"{key.ljust(key_width)}{value}")
        idx += 1
    return "\n".join(lines)

def chunk_into_n_parts(lst, n):
    if n <= 0:
        return []
    length = len(lst)
    base, rem = divmod(length, n)
    size = base + 1 if rem > 0 else base
    return [lst[:size]] + chunk_into_n_parts(lst[size:], n - 1)

