def date_n_days_before_year_end(year, n):
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    lengths = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    cumulative = []
    total = 0
    for length in lengths:
        total += length
        cumulative.append(total)
    target = (366 if leap else 365) - n
    for month_index, cum in enumerate(cumulative):
        if target <= cum:
            day = target - (cumulative[month_index - 1] if month_index > 0 else 0)
            return (month_index + 1, day)
    return None

