def free_time_slots(intervals, day_start, day_end):
    points = [day_start] + [p for pair in intervals for p in pair] + [day_end]
    gaps = []
    for i in range(0, len(points) - 1, 2):
        if points[i] < points[i + 1]:
            gaps.append((points[i], points[i + 1]))
    return gaps

def is_valid_markdown_link(s):
    if not s.startswith('[') or not s.endswith(')'):
        return False
    close_bracket = s.find(']')
    if close_bracket == -1:
        return False
    text = s[1:close_bracket]
    if not text or ']' in text:
        return False
    if s[close_bracket + 1:close_bracket + 2] != '(':
        return False
    url = s[close_bracket + 2:-1]
    if not url or any(c.isspace() for c in url):
        return False
    return url.startswith('http://') or url.startswith('https://')

