def sum_of_even_divisors(n):
    total = 0
    d = 2
    while d <= n:
        if n % d == 0:
            total += d
        d += 2
    return total

def longest_increasing_run_length(lst):
    if not lst:
        return 0
    best = run = 1
    for prev, cur in zip(lst, lst[1:]):
        run = run + 1 if cur > prev else 1
        best = max(best, run)
    return best

def oxford_join_or(items):
    if not items:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' or ' + items[1]
    text = items[0]
    for word in items[1:-1]:
        text += ', ' + word
    text += ', or ' + items[-1]
    return text

